python3 -c "
from PIL import Image
img = Image.open('/app/output/final_poster.png')

# First ranking row dot at (80, ~549)
for y in range(540, 560):
    p = img.getpixel((80, y))
    if sum(p) > 100:
        print(f'Dot at (80, {y}): #{p[0]:02x}{p[1]:02x}{p[2]:02x}')

# Check ranking table row 1 model name (GPT-5)
for x in range(105, 400, 2):
    for y in range(540, 560, 2):
        p = img.getpixel((x, y))
        if sum(p) > 200:
            print(f'Text at ({x}, {y}): #{p[0]:02x}{p[1]:02x}{p[2]:02x}')
            break
    else:
        continue
    break

# Check a bar in the ranking
for x in range(480, 700, 5):
    for y in range(540, 560, 2):
        p = img.getpixel((x, y))
        if p[1] > p[0] + 50:  # green
            print(f'Bar at ({x}, {y}): #{p[0]:02x}{p[1]:02x}{p[2]:02x}')
            break
    else:
        continue
    break

print('All good')
"

